"""Exceptions raised at the boundary where external input becomes domain data.

Every error here corresponds to one thing the audit trail must never accept
silently: a malformed actor, an outcome outside the fixed vocabulary, an
event id that does not match its own recorded content, or a sequence number
that breaks the gapless append-only chain.
"""

from __future__ import annotations


class AuditLogError(Exception):
    """Base class for every domain error the audit log raises."""


class MalformedActorError(AuditLogError):
    """Raised when an actor string is not a valid ``kind:name`` identity."""


class MalformedActionError(AuditLogError):
    """Raised when an action string does not match the canonical shape."""


class UnknownOutcomeError(AuditLogError):
    """Raised when an outcome is outside the fixed allowed/denied vocabulary."""


class MalformedTimestampError(AuditLogError):
    """Raised when ``recorded_at`` is not a canonical UTC timestamp."""


class InvalidEventIdError(AuditLogError):
    """Raised when an event id is malformed or does not match its content."""


class SequenceError(AuditLogError):
    """Raised when a sequence number is not a positive gapless increment."""


class MalformedEventError(AuditLogError):
    """Raised when a stored entry is missing a required field."""


class StorageCorruptionError(AuditLogError):
    """Raised when a log-store file cannot be read as a supported format."""


class ArchiveStoreError(AuditLogError):
    """Raised when a write is attempted against a read-only legacy archive."""


class MalformedRouteError(AuditLogError):
    """Raised when a route's method or path is not well-formed."""


class RouteNotFoundError(AuditLogError):
    """Raised when no route matches a requested method and path."""


class AccessDeniedError(AuditLogError):
    """Raised when an actor's kind does not hold a required permission."""

"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route table before reading a body."""

    # Look up the route using the same path spelling the rest of the service uses.
    return canonical_path(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

"""Route and access-policy models shared by authentication and dispatch.

``auditlog.paths`` normalizes a raw request path to one canonical spelling.
This module builds on that: ``Route`` binds a canonical (method, path) to the
``Permission`` it requires, and ``AccessPolicy`` decides which actor kinds
hold which permissions. An HTTP transport looks up a route with
``route_for`` (which uses ``auth_path``, matching the README's requirement
that authentication and dispatch share one path helper) and then calls
``AccessPolicy.authorize`` before invoking the service.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum

from .errors import AccessDeniedError, MalformedRouteError, RouteNotFoundError
from .models import Actor, ActorKind
from .paths import auth_path

_HTTP_METHODS = frozenset({"GET", "POST", "PUT", "PATCH", "DELETE"})


class Permission(str, Enum):
    """The fixed set of operations a route or actor kind can be granted."""

    RECORD = "record"
    QUERY = "query"
    REPAIR = "repair"


@dataclass(frozen=True)
class Route:
    """One HTTP endpoint: a method, a canonical path, and the permission it requires."""

    method: str
    path: str
    permission: Permission

    def __post_init__(self) -> None:
        if self.method not in _HTTP_METHODS:
            raise MalformedRouteError(
                f"method {self.method!r} must be one of {sorted(_HTTP_METHODS)}"
            )
        if not self.path.startswith("/"):
            raise MalformedRouteError(f"path {self.path!r} must start with '/'")
        if auth_path(self.path) != self.path:
            raise MalformedRouteError(
                f"path {self.path!r} must already be in canonical form (got "
                f"{auth_path(self.path)!r})"
            )


ROUTES: tuple[Route, ...] = (
    Route("POST", "/events", Permission.RECORD),
    Route("GET", "/events", Permission.QUERY),
    Route("POST", "/repair", Permission.REPAIR),
)


def route_for(method: str, raw_path: str) -> Route:
    """Resolve a raw request to the route table, using the shared path helper."""

    method = method.upper()
    path = auth_path(raw_path)
    for route in ROUTES:
        if route.method == method and route.path == path:
            return route
    raise RouteNotFoundError(f"no route for {method} {raw_path!r}")


@dataclass(frozen=True)
class AccessPolicy:
    """Maps each actor kind to the fixed set of permissions it holds."""

    grants: dict[ActorKind, frozenset[Permission]]

    def __post_init__(self) -> None:
        for kind, permissions in self.grants.items():
            if not isinstance(kind, ActorKind):
                raise MalformedRouteError(f"policy grant key {kind!r} must be an ActorKind")
            for permission in permissions:
                if not isinstance(permission, Permission):
                    raise MalformedRouteError(
                        f"policy grant for {kind!r} contains non-Permission {permission!r}"
                    )

    def is_allowed(self, actor: Actor, permission: Permission) -> bool:
        return permission in self.grants.get(actor.kind, frozenset())

    def authorize(self, actor: Actor, permission: Permission) -> None:
        """Raise ``AccessDeniedError`` unless ``actor``'s kind holds ``permission``."""

        if not self.is_allowed(actor, permission):
            raise AccessDeniedError(
                f"actor kind {actor.kind.value!r} does not hold permission {permission.value!r}"
            )


DEFAULT_POLICY = AccessPolicy(
    grants={
        ActorKind.OPERATOR: frozenset({Permission.RECORD, Permission.QUERY, Permission.REPAIR}),
        ActorKind.SERVICE: frozenset({Permission.QUERY}),
        ActorKind.SYSTEM: frozenset({Permission.RECORD, Permission.QUERY, Permission.REPAIR}),
    }
)

"""Tests for the strict domain models in auditlog.models."""

from __future__ import annotations

import unittest

from auditlog.errors import (
    InvalidEventIdError,
    MalformedActionError,
    MalformedActorError,
    MalformedEventError,
    MalformedTimestampError,
    SequenceError,
    UnknownOutcomeError,
)
from auditlog.models import (
    Actor,
    ActorKind,
    Outcome,
    content_digest,
    load_event,
    new_event,
    parse_timestamp,
    validate_action,
    validate_event_id,
    validate_sequence,
    verify_event,
)


class ActorTests(unittest.TestCase):
    def test_parses_kind_and_name(self) -> None:
        actor = Actor.parse("operator:mina")
        self.assertEqual(actor.kind, ActorKind.OPERATOR)
        self.assertEqual(actor.name, "mina")
        self.assertEqual(str(actor), "operator:mina")

    def test_rejects_missing_separator(self) -> None:
        with self.assertRaises(MalformedActorError):
            Actor.parse("operator-mina")

    def test_rejects_unknown_kind(self) -> None:
        with self.assertRaises(MalformedActorError):
            Actor.parse("robot:mina")

    def test_rejects_extra_separator(self) -> None:
        with self.assertRaises(MalformedActorError):
            Actor.parse("operator:mi:na")

    def test_rejects_empty_name(self) -> None:
        with self.assertRaises(MalformedActorError):
            Actor.parse("operator:")

    def test_direct_construction_is_also_validated(self) -> None:
        with self.assertRaises(MalformedActorError):
            Actor(kind=ActorKind.OPERATOR, name="Mina")


class ActionTests(unittest.TestCase):
    def test_accepts_dotted_lowercase_action(self) -> None:
        self.assertEqual(validate_action("policy.update"), "policy.update")

    def test_rejects_action_without_a_dot(self) -> None:
        with self.assertRaises(MalformedActionError):
            validate_action("update")

    def test_rejects_uppercase_action(self) -> None:
        with self.assertRaises(MalformedActionError):
            validate_action("Policy.Update")


class OutcomeTests(unittest.TestCase):
    def test_accepts_known_outcomes(self) -> None:
        self.assertEqual(Outcome.parse("allowed"), Outcome.ALLOWED)
        self.assertEqual(Outcome.parse("denied"), Outcome.DENIED)

    def test_rejects_unknown_outcome(self) -> None:
        with self.assertRaises(UnknownOutcomeError):
            Outcome.parse("maybe")


class TimestampTests(unittest.TestCase):
    def test_accepts_canonical_utc_timestamp(self) -> None:
        parse_timestamp("2024-03-02T09:04:00Z")

    def test_accepts_fractional_seconds(self) -> None:
        parse_timestamp("2024-03-02T09:04:00.000Z")

    def test_rejects_non_utc_offset(self) -> None:
        with self.assertRaises(MalformedTimestampError):
            parse_timestamp("2024-03-02T09:04:00+01:00")

    def test_rejects_missing_zone(self) -> None:
        with self.assertRaises(MalformedTimestampError):
            parse_timestamp("2024-03-02T09:04:00")


class ContentDigestTests(unittest.TestCase):
    def test_identity_is_the_recorded_content(self) -> None:
        first = content_digest("operator:mina", "policy.update", "allowed", "T1")
        same = content_digest("operator:mina", "policy.update", "allowed", "T1")
        self.assertEqual(first, same)

    def test_fields_cannot_collide_by_concatenation(self) -> None:
        left = content_digest("a", "bc", "d", "e")
        right = content_digest("ab", "c", "d", "e")
        self.assertNotEqual(left, right)


class ValidateEventIdTests(unittest.TestCase):
    def test_rejects_malformed_id_shape(self) -> None:
        with self.assertRaises(InvalidEventIdError):
            validate_event_id("not-hex", "operator:mina", "policy.update", "allowed", "T1")

    def test_rejects_id_that_does_not_match_content(self) -> None:
        digest = content_digest("operator:mina", "policy.update", "allowed", "T1")
        with self.assertRaises(InvalidEventIdError):
            validate_event_id(digest, "operator:mina", "policy.update", "denied", "T1")

    def test_accepts_matching_id(self) -> None:
        digest = content_digest("operator:mina", "policy.update", "allowed", "T1")
        validate_event_id(digest, "operator:mina", "policy.update", "allowed", "T1")


class ValidateSequenceTests(unittest.TestCase):
    def test_accepts_gapless_increment(self) -> None:
        validate_sequence(1, 2)

    def test_rejects_a_gap(self) -> None:
        with self.assertRaises(SequenceError):
            validate_sequence(1, 3)

    def test_rejects_a_repeat(self) -> None:
        with self.assertRaises(SequenceError):
            validate_sequence(2, 2)

    def test_rejects_going_backwards(self) -> None:
        with self.assertRaises(SequenceError):
            validate_sequence(5, 1)


class NewEventTests(unittest.TestCase):
    def test_builds_an_event_with_a_derived_id(self) -> None:
        event = new_event("operator:mina", "policy.update", "allowed", "2024-03-02T09:04:00Z", 1)
        self.assertEqual(event.event_id, event.recomputed_id())
        self.assertEqual(event.sequence, 1)

    def test_rejects_malformed_actor(self) -> None:
        with self.assertRaises(MalformedActorError):
            new_event("mina", "policy.update", "allowed", "2024-03-02T09:04:00Z", 1)

    def test_rejects_unknown_outcome(self) -> None:
        with self.assertRaises(UnknownOutcomeError):
            new_event("operator:mina", "policy.update", "maybe", "2024-03-02T09:04:00Z", 1)

    def test_rejects_non_positive_sequence(self) -> None:
        with self.assertRaises(SequenceError):
            new_event("operator:mina", "policy.update", "allowed", "2024-03-02T09:04:00Z", 0)

    def test_rejects_malformed_action(self) -> None:
        with self.assertRaises(MalformedActionError):
            new_event("operator:mina", "update", "allowed", "2024-03-02T09:04:00Z", 1)


class LoadEventTests(unittest.TestCase):
    def _valid_raw(self) -> dict:
        digest = content_digest("operator:mina", "policy.update", "allowed", "2024-03-02T09:04:00Z")
        return {
            "event_id": digest,
            "sequence": 1,
            "actor": "operator:mina",
            "action": "policy.update",
            "outcome": "allowed",
            "recorded_at": "2024-03-02T09:04:00Z",
            "metadata": {"note": "x"},
        }

    def test_loads_a_valid_record(self) -> None:
        event = load_event(self._valid_raw())
        self.assertEqual(event.sequence, 1)
        self.assertEqual(event.metadata, {"note": "x"})

    def test_rejects_missing_field(self) -> None:
        raw = self._valid_raw()
        del raw["outcome"]
        with self.assertRaises(MalformedEventError):
            load_event(raw)

    def test_rejects_tampered_content(self) -> None:
        raw = self._valid_raw()
        raw["outcome"] = "denied"
        with self.assertRaises(InvalidEventIdError):
            load_event(raw)

    def test_rejects_broken_sequence_type(self) -> None:
        raw = self._valid_raw()
        raw["sequence"] = "1"
        with self.assertRaises(SequenceError):
