python3 - <<'EOF'
import re, pathlib

files = sorted(pathlib.Path("maintenance/inputs/environment-results").iterdir())
cycle = [("review","linux-x86_64"), ("documented","windows-x86_64"), ("follow-up","freebsd-x86_64"), ("compatible","macos-arm64")]

def extract(f):
    text = f.read_text()
    name = f.name
    pairs = []
    if name.endswith(".yaml"):
        for line in text.splitlines():
            m = re.search(r"platform: ([a-z0-9-]+), status: ([a-z-]+),", line)
            if m: pairs.append((m.group(2), m.group(1)))
    elif name.endswith(".md"):
        for line in text.splitlines():
            m = re.search(r"Platform: ([a-z0-9-]+) \| Status: ([a-z-]+) \|", line)
            if m: pairs.append((m.group(2), m.group(1)))
    elif name.endswith(".csv"):
        for line in text.splitlines()[1:]:
            m = re.match(r'"[^"]+","([a-z0-9-]+)","([a-z-]+)",', line)
            if m: pairs.append((m.group(2), m.group(1)))
    elif name.endswith(".jsonl"):
        import json
        for line in text.splitlines():
            if not line.strip(): continue
            d = json.loads(line)
            pairs.append((d["status"], d["platform"]))
    elif name.endswith(".log"):
        for line in text.splitlines():
            m = re.search(r"platform=([a-z0-9-]+) status=([a-z-]+) ", line)
            if m: pairs.append((m.group(2), m.group(1)))
    return pairs

for f in files:
    pairs = extract(f)
    mismatches = 0
    for i, (status, platform) in enumerate(pairs):
        expected = cycle[i % 4]
        if (status, platform) != expected:
            mismatches += 1
    print(f.name, "rows:", len(pairs), "mismatches:", mismatches)
EOF

python3 - <<'EOF'
import re, pathlib, json

files = sorted(pathlib.Path("maintenance/inputs/environment-results").iterdir())
cycle = [("review","linux-x86_64"), ("documented","windows-x86_64"), ("follow-up","freebsd-x86_64"), ("compatible","macos-arm64")]

def extract(f):
    text = f.read_text()
    name = f.name
    pairs = []
    if name.endswith(".yaml"):
        for line in text.splitlines():
            m = re.search(r"platform: ([a-z0-9_-]+), status: ([a-z-]+),", line)
            if m: pairs.append((m.group(2), m.group(1)))
    elif name.endswith(".md"):
        for line in text.splitlines():
            m = re.search(r"Platform: ([a-z0-9_-]+) \| Status: ([a-z-]+) \|", line)
            if m: pairs.append((m.group(2), m.group(1)))
    elif name.endswith(".csv"):
        for line in text.splitlines()[1:]:
            m = re.match(r'"[^"]+","([a-z0-9_-]+)","([a-z-]+)",', line)
            if m: pairs.append((m.group(2), m.group(1)))
    elif name.endswith(".jsonl"):
        for line in text.splitlines():
            if not line.strip(): continue
            d = json.loads(line)
            pairs.append((d["status"], d["platform"]))
    elif name.endswith(".log"):
        for line in text.splitlines():
            m = re.search(r"platform=([a-z0-9_-]+) status=([a-z-]+) ", line)
            if m: pairs.append((m.group(2), m.group(1)))
    return pairs

total = 0
for f in files:
    pairs = extract(f)
    mismatches = 0
    for i, (status, platform) in enumerate(pairs):
        expected = cycle[i % 4]
        if (status, platform) != expected:
