python3 - <<'EOF'
import re, pathlib, json

files = sorted(pathlib.Path("maintenance/inputs/environment-results").iterdir())

def case_ids(f):
    text = f.read_text()
    name = f.name
    ids = []
    if name.endswith(".yaml"):
        ids = re.findall(r"case: '([^']+)'", text)
    elif name.endswith(".md"):
        ids = re.findall(r"\*\*([^*]+)\*\*", text)
    elif name.endswith(".csv"):
        ids = re.findall(r'^"([^"]+)",', text, re.MULTILINE)
    elif name.endswith(".jsonl"):
        for line in text.splitlines():
            if line.strip():
                ids.append(json.loads(line)["case"])
    elif name.endswith(".log"):
        ids = re.findall(r"case=(\S+)", text)
    return ids

for f in files:
    ids = case_ids(f)
    print(f.name, "count:", len(ids), "unique:", len(set(ids)))
EOF

