input.command:
python3 - <<'EOF'
import re, pathlib, json

files = sorted(pathlib.Path("maintenance/inputs/restart-results").iterdir())
cycle = [("review","linux-x86_64"), ("documented","windows-x86_64"), ("follow-up","freebsd-x86_64"), ("compatible","macos-arm64")]

def extract(f):
    text = f.read_text()
    name = f.name
    pairs, ids = [], []
    if name.endswith(".yaml"):
        for line in text.splitlines():
            m = re.search(r"case: '([^']+)', platform: ([a-z0-9_-]+), status: ([a-z-]+),", line)
            if m: ids.append(m.group(1)); pairs.append((m.group(3), m.group(2)))
    elif name.endswith(".md"):
        for line in text.splitlines():
            m = re.search(r"\*\*([^*]+)\*\* \| Platform: ([a-z0-9_-]+) \| Status: ([a-z-]+) \|", line)
            if m: ids.append(m.group(1)); pairs.append((m.group(3), m.group(2)))
    elif name.endswith(".csv"):
        for line in text.splitlines()[1:]:
            m = re.match(r'"([^"]+)","([a-z0-9_-]+)","([a-z-]+)",', line)
            if m: ids.append(m.group(1)); pairs.append((m.group(3), m.group(2)))
    elif name.endswith(".jsonl"):
        for line in text.splitlines():
            if not line.strip(): continue
            d = json.loads(line)
            ids.append(d["case"]); pairs.append((d["status"], d["platform"]))
    elif name.endswith(".log"):
        for line in text.splitlines():
            m = re.search(r"case=(\S+) platform=([a-z0-9_-]+) status=([a-z-]+) ", line)
            if m: ids.append(m.group(1)); pairs.append((m.group(3), m.group(2)))
    return ids, pairs

total = 0
for f in files:
    ids, pairs = extract(f)
    mismatches = sum(1 for i, sp in enumerate(pairs) if sp != cycle[i % 4])
    total += len(pairs)
    print(f.name, "rows:", len(pairs), "unique ids:", len(set(ids)), "mismatches:", mismatches)
print("total rows:", total)
EOF

